head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > setImageSrc]<br/>inputType='textImage' 인 Body Column 의 imageSrc 속성을 설정합니다.",
    "validation" : [
        "columnInfo(필수) 파라미터는 Row 가 MultiLine 이어도 모든 Column 은 고유의 인덱스값을 가져야 합니다."
    ]
}



scwin.onpageload = async function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성 (비동기 dynamicCreate 완료까지 대기)
    await scwin.comp_init();

    // 파라미터 기본 선택값 설정 (정적 select1 은 초기 selectedIndex 미적용)
    par_columnInfo.setSelectedIndex(1);
    par_src.setSelectedIndex(0);

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 (Target 재생성 버튼 클릭 시 재실행)
//  - Body 를 MultiLine 으로 구성 : gBody 에 <w2:row> 2개 -> 한 데이터 Row 가 2 Line 으로 표시
//  - Line1 : col1(인덱스 0, text) / col2(인덱스 1, textImage)
//  - Line2 : col3(인덱스 2, textImage) / col4(인덱스 3, text)
//    · gBody column 의 id 는 바인딩 DataList(dlt_bind) 의 컬럼 id 와 동일해야 데이터가 렌더됨
//    · Line2 의 첫 Column 인덱스가 0 이 아닌 2 로 이어짐 -> Column 인덱스는 Line 마다 초기화되지 않고 고유함
scwin.comp_init = async function () {
    // 기존 target / dataList 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let strNameSpace = $c.gcm.getNameSpace();
    let grp_comp = $c.gcm.getTestGroup();

    // 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] Body 가 MultiLine(2 Line) 입니다. 한 데이터 Row 가 2 Line 에 걸쳐 표시되며 데이터 Row 는 3개(Row 0~2) 입니다.\nLine1 : col1(columnInfo 0, text) / col2(columnInfo 1, textImage)\nLine2 : col3(columnInfo 2, textImage) / col4(columnInfo 3, text)\ntextImage Column 은 columnInfo 1(Line1) 과 columnInfo 2(Line2) 이며, columnInfo 0 / 3 은 text Column 입니다.\n[절차] columnInfo / src 를 선택하고 setImageSrc 버튼을 클릭하세요. columnInfo 1 과 columnInfo 2 에 서로 다른 이미지를 각각 설정해 보세요.\n[확인] 결과창의 적용 Column 위치(Line / Line 내 순번) 로 지정한 인덱스가 어느 Line 을 가리키는지 확인하고, columnInfo 1 과 2 의 두 결과 줄을 비교해 서로 다른 Line 에 각각 적용되는지, 적용 Column 은 전 Row 에 같은 이미지가 표시되는지 확인하세요."', '', 'label1');

    // === 바인딩 DataList(dlt_bind) : col1~col4 ===
    $c.gcm.createBasicDataList('', '', 'dlt_bind');
    dlt_bind.setJSON([
        { "col1": "서울 강남점", "col2": "수정", "col3": "삭제", "col4": "A등급" },
        { "col1": "부산 해운대점", "col2": "수정", "col3": "삭제", "col4": "B등급" },
        { "col1": "대구 수성점", "col2": "수정", "col3": "삭제", "col4": "C등급" }
    ]);

    // target 그리드 직접 구성 (Body MultiLine : gBody 에 <w2:row> 2개)
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" id="" style="width:560px;height:340px;">';
    strTarget += '<w2:caption style="" id="caption1" value="setImageSrc MultiLine test grid"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="280" style="" inputType="text" id="hcol1" value="col1 (0, text)"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="hcol2" value="col2 (1, textImage)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '<w2:row style="" id="hrow2">';
    strTarget += '<w2:column width="280" style="" inputType="text" id="hcol3" value="col3 (2, textImage)"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="hcol4" value="col4 (3, text)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    // Line1 : 인덱스 0 / 1
    //  - body column 의 id 는 dataList(= 바인딩 DataList 의 컬럼 id) 와 반드시 일치해야 셀에 데이터가 표시됨
    strTarget += '<w2:row style="" id="brow1">';
    strTarget += '<w2:column width="280" style="" inputType="text" id="col1" dataList="col1"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="textImage" viewType="icon" id="col2" dataList="col2"></w2:column>';
    strTarget += '</w2:row>';
    // Line2 : 인덱스 2 / 3 (Line 이 바뀌어도 인덱스는 0 으로 초기화되지 않고 이어짐)
    strTarget += '<w2:row style="" id="brow2">';
    strTarget += '<w2:column width="280" style="" inputType="textImage" viewType="icon" id="col3" dataList="col3"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="col4" dataList="col4"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// Body Cell 의 표시 텍스트 / 이미지 경로 확인
scwin.getCellImgInfo = function (rowIndex, colIndex) {
    let cellEl = document.querySelector("td[id*='target1_cell_" + rowIndex + "_" + colIndex + "']");
    if (!cellEl) {
        return "(Cell 없음)";
    }
    let imgEl = cellEl.querySelector("img");
    let src = (imgEl && imgEl.getAttribute("src")) ? imgEl.getAttribute("src") : "(이미지 미표시)";
    return cellEl.textContent + " / " + src;
}



// columnInfo 가 지목한 Column 의 실제 표시 위치(Line / Line 내 순번) 확인
//  - MultiLine 이어도 Column 인덱스는 Line 마다 초기화되지 않으므로, 지정 인덱스가 어느 Line 을 가리키는지 함께 표기
scwin.getColumnPos = function (colIndex) {
    let cellEl = document.querySelector("td[id*='target1_cell_0_" + colIndex + "']");
    if (!cellEl) {
        return "(Column 없음)";
    }
    let tr = cellEl.parentElement;
    let trIdx = Array.prototype.indexOf.call(tr.parentElement.children, tr);
    let lineNo = (trIdx % 2) + 1;
    let colNoInLine = Array.prototype.indexOf.call(tr.children, cellEl) + 1;
    return "Line " + lineNo + " 의 " + colNoInLine + " 번째 Column";
}



scwin.btn_setImageSrc_onclick = function () {
    let columnInfo = Number(par_columnInfo.getText());
    let src = par_src.getText();

    target1.setImageSrc(columnInfo, src);

    // Column 전체 Cell 의 표시 텍스트 / 이미지 경로 수집 (데이터 Row 3개)
    let detail = [];
    for (let i = 0; i < 3; i++) {
        detail.push("[Row " + i + "] " + scwin.getCellImgInfo(i, columnInfo));
    }

    wf_body_bottom.getObj("scwin").setReturnValue("setImageSrc(" + columnInfo + ", '" + src + "') 호출 후 적용 Column (" + scwin.getColumnPos(columnInfo) + ") 전체 Cell (표시 텍스트 / 이미지 경로) : " + detail.join(", "));
}
